const $=id=>document.getElementById(id);
const controls=['preset','colors','simplify','speckle','mode','threshold'];
let source=null,svg='',rasterURL='',vectorURL='',worker=null,timer=null,busy=false,dirty=false,zoom=1,view='compare',generation=0;
const presets={logo:{colors:8,simplify:1.2,speckle:4,mode:'spline'},illustration:{colors:24,simplify:.6,speckle:2,mode:'spline'},bw:{colors:2,simplify:.8,speckle:4,mode:'spline'}};
function message(text){$('notice').textContent=text;$('notice').hidden=!text;}
function status(text,state='ready'){$('status').textContent=text;$('status-dot').style.background=state==='error'?'#c85d39':state==='pending'?'#d49a49':'#4e9364';}
function updateLabels(){for(const id of ['colors','simplify','speckle','threshold']) $(id+'-value').textContent=$(id).value+(id==='speckle'?' px':'');const bw=$('preset').value==='bw';$('bw-control').hidden=!bw;$('colors').disabled=bw||busy;}
function setBusy(value){busy=value;$('busy').hidden=!value;$('cancel').hidden=!value;for(const id of [...controls,'reset','trace','upload','sample','file']) $(id).disabled=value;updateLabels();$('trace').textContent=value?'Sedang memproses…':'Vektorisasi ↗';$('download').disabled=value||dirty||!svg;}
function markDirty(){dirty=true;$('download').disabled=true;status('Pengaturan berubah · klik Vektorisasi','pending');updateLabels();}
function applyPreset(){const values=presets[$('preset').value];for(const [id,value] of Object.entries(values)) $(id).value=value;$('threshold').value=128;markDirty();}
function options(){return {preset:$('preset').value==='bw'?'bw':'poster',clustering:$('preset').value==='bw'?'bw':'color-cluster',hierarchical:'cutout',mode:$('mode').value,maxColors:Number($('colors').value),simplify:Number($('simplify').value),filterSpeckle:Number($('speckle').value),binaryThreshold:Number($('threshold').value),pathPrecision:2,optimize:1};}
function stopWorker(){if(worker){worker.terminate();worker=null;}clearTimeout(timer);timer=null;}
function failed(text){stopWorker();dirty=true;setBusy(false);message(text);status('Proses belum selesai','error');}
function renderView(){const has=Boolean(svg);const showResult=has&&view!=='original';$('vector').hidden=!showResult;$('original').hidden=has&&(view==='vector'||view==='outline');$('split').hidden=!has||view!=='compare';$('split-line').hidden=!has||view!=='compare';$('vector').style.clipPath=view==='compare'?`inset(0 0 0 ${$('split').value}%)`:'none';$('split-line').style.left=$('split').value+'%';$('label-left').textContent=view==='compare'?'ASLI / PIKSEL':view==='original'?'GAMBAR ASLI':view==='outline'?'OUTLINE / PATH':'HASIL VEKTOR';$('label-right').hidden=view!=='compare';for(const b of document.querySelectorAll('[data-view]')) b.setAttribute('aria-pressed',b.dataset.view===view);}
function showSVG(){if(vectorURL)URL.revokeObjectURL(vectorURL);let display=svg;if(view==='outline'){const doc=new DOMParser().parseFromString(svg,'image/svg+xml');for(const node of doc.querySelectorAll('path,polygon,rect,circle,ellipse,polyline')){node.setAttribute('fill','none');node.setAttribute('stroke','#344d3c');node.setAttribute('stroke-width','0.7');node.setAttribute('vector-effect','non-scaling-stroke');}display=new XMLSerializer().serializeToString(doc);}vectorURL=URL.createObjectURL(new Blob([display],{type:'image/svg+xml'}));$('vector').src=vectorURL;renderView();}
function sizeArtboard(){if(!source)return;const width=Math.max(180,$('viewport').clientWidth-70);const height=window.innerWidth<=700?290:430;const scale=Math.min(width/source.width,height/source.height);$('artboard').style.width=Math.round(source.width*scale*zoom)+'px';$('artboard').style.height=Math.round(source.height*scale*zoom)+'px';$('zoom-label').value=Math.round(zoom*100)+'%';}
function trace(){if(!source||busy)return;message('');stopWorker();dirty=true;setBusy(true);status('Vektorisasi berlangsung','pending');$('busy-label').textContent='Memuat mesin VTracer…';const job=++generation;worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});timer=setTimeout(()=>{if(job===generation)failed('Proses melewati 60 detik. Kurangi ukuran gambar atau gunakan jumlah warna yang lebih sedikit.');},60000);worker.onerror=()=>{if(job===generation)failed('Mesin tidak dapat berjalan. Muat ulang halaman lalu coba gambar yang lebih kecil.');};worker.onmessage=({data})=>{if(job!==generation)return;if(data.type==='ready'){$('busy-label').textContent='Menyusun kurva dan warna…';return;}if(data.type==='error'){failed('Vektorisasi gagal: '+data.message);return;}stopWorker();svg=data.svg;dirty=false;setBusy(false);showSVG();const doc=new DOMParser().parseFromString(svg,'image/svg+xml');$('stat-paths').textContent=doc.querySelectorAll('path').length.toLocaleString('id-ID');$('stat-colors').textContent=new Set([...doc.querySelectorAll('[fill]')].map(el=>el.getAttribute('fill')).filter(v=>v!=='none')).size;$('stat-size').textContent=(new Blob([svg]).size/1024).toFixed(1)+' KB';$('stat-time').textContent=(data.elapsed/1000).toFixed(2)+' dtk';status('Vektor siap · SVG dapat diunduh');};const rgba=source.rgba.slice().buffer;worker.postMessage({rgba,width:source.width,height:source.height,options:options()},[rgba]);}
function clearResult(){svg='';dirty=true;if(vectorURL){URL.revokeObjectURL(vectorURL);vectorURL='';}$('vector').removeAttribute('src');for(const id of ['paths','colors','size','time']) $('stat-'+id).textContent='—';zoom=1;renderView();sizeArtboard();}
function setSource(canvas,name,meta){source={width:canvas.width,height:canvas.height,rgba:canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height).data,name};if(rasterURL)URL.revokeObjectURL(rasterURL);rasterURL=canvas.toDataURL('image/png');$('original').src=rasterURL;$('filename').textContent=name;$('filemeta').textContent=meta;clearResult();trace();}
async function loadFile(file){if(!file||busy)return;const token=++generation;message('');if(file.size>20*1024*1024){message('Ukuran file maksimal 20 MB. Pilih gambar yang lebih kecil.');return;}if(!/\.(png|jpe?g|webp|bmp|gif)$/i.test(file.name)&&!['image/png','image/jpeg','image/webp','image/bmp','image/gif'].includes(file.type)){message('Format belum didukung. Gunakan PNG, JPG, WebP, BMP, atau GIF.');return;}status('Membaca gambar…','pending');try{const bitmap=await createImageBitmap(file);if(token!==generation){bitmap.close();return;}if(bitmap.width*bitmap.height>40000000){bitmap.close();throw Error('Gambar melebihi 40 megapiksel. Perkecil terlebih dahulu.');}const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height),Math.sqrt(2000000/(bitmap.width*bitmap.height)));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const originalSize=`${bitmap.width} × ${bitmap.height}`;bitmap.close();setSource(canvas,file.name,`${canvas.width} × ${canvas.height} px · ${(file.size/1024/1024).toFixed(2)} MB`);if(scale<1)message(`Gambar ${originalSize} diperkecil menjadi ${canvas.width} × ${canvas.height} untuk menjaga kinerja browser. SVG mengikuti ukuran pemrosesan.`);if(/\.gif$/i.test(file.name))message('GIF diproses sebagai gambar diam dari frame pertama.');}catch(error){if(token!==generation)return;message(error.message||'Gambar tidak dapat dibaca. Coba file lain.');status(svg?'Hasil sebelumnya tetap tersedia':'Gagal membaca gambar','error');}}
function sample(){if(busy)return;const c=document.createElement('canvas');c.width=c.height=640;const ctx=c.getContext('2d');ctx.fillStyle='#f3ecd9';ctx.fillRect(0,0,640,640);ctx.save();ctx.translate(320,314);ctx.fillStyle='#e3a04f';ctx.beginPath();ctx.arc(0,0,225,0,Math.PI*2);ctx.fill();ctx.save();ctx.beginPath();ctx.arc(0,0,212,0,Math.PI*2);ctx.clip();ctx.fillStyle='#efc978';ctx.fillRect(-220,-220,440,440);ctx.fillStyle='#d97443';ctx.beginPath();ctx.arc(68,-76,62,0,Math.PI*2);ctx.fill();function poly(points,color){ctx.fillStyle=color;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fill();}poly([[-250,120],[-73,-121],[126,150]],'#9aa68a');poly([[-122,140],[51,-96],[248,155]],'#657d62');poly([[-150,100],[-73,-121],[-8,-20],[-52,-42],[-72,-12],[-91,-48]],'#f3ecd9');poly([[-230,196],[-60,-16],[126,203]],'#345949');poly([[3,223],[144,9],[284,224]],'#28483d');poly([[-280,162],[-164,69],[-55,230]],'#3f6652');ctx.fillStyle='#1d3c34';ctx.fillRect(-240,188,480,80);function tree(x,y,s){poly([[x,y-s],[x-s*.35,y-s*.38],[x-s*.14,y-s*.38],[x-s*.5,y],[x+s*.5,y],[x+s*.14,y-s*.38],[x+s*.35,y-s*.38]],'#1d3c34');ctx.fillRect(x-3,y,6,s*.15);}tree(-128,134,113);tree(145,170,125);tree(177,184,90);ctx.restore();ctx.strokeStyle='#f3ecd9';ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,0,219,0,Math.PI*2);ctx.stroke();ctx.restore();ctx.fillStyle='#345949';ctx.textAlign='center';ctx.font='bold 24px Georgia';ctx.fillText('THE GREAT OUTDOORS',320,583);setSource(c,'mountain-badge.png','640 × 640 px · Contoh raster buatan studio');}
$('upload').onclick=()=>$('file').click();$('file').onchange=()=>{loadFile($('file').files[0]);$('file').value='';};$('trace').onclick=trace;$('cancel').onclick=()=>{generation++;stopWorker();dirty=true;setBusy(false);status('Dibatalkan · klik Vektorisasi untuk mengulang','pending');};$('sample').onclick=sample;$('reset').onclick=()=>{$('preset').value='logo';applyPreset();};$('preset').onchange=applyPreset;for(const id of controls.filter(x=>x!=='preset')) $(id).addEventListener('input',markDirty);
$('split').oninput=renderView;for(const button of document.querySelectorAll('[data-view]')) button.onclick=()=>{view=button.dataset.view;if(svg)showSVG();else renderView();};$('zoom-in').onclick=()=>{zoom=Math.min(4,zoom+.25);sizeArtboard();};$('zoom-out').onclick=()=>{zoom=Math.max(.25,zoom-.25);sizeArtboard();};$('fit').onclick=()=>{zoom=1;sizeArtboard();};new ResizeObserver(sizeArtboard).observe($('viewport'));
$('download').onclick=()=>{if(!svg||dirty||busy)return;const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));const link=document.createElement('a');link.href=url;link.download=source.name.replace(/\.[^.]+$/,'')+'-garis.svg';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
let dragDepth=0;document.addEventListener('dragenter',event=>{if(!event.dataTransfer.types.includes('Files'))return;event.preventDefault();dragDepth++;if(!busy)$('drop-overlay').hidden=false;});document.addEventListener('dragover',event=>{if(event.dataTransfer.types.includes('Files'))event.preventDefault();});document.addEventListener('dragleave',()=>{if(--dragDepth<=0){dragDepth=0;$('drop-overlay').hidden=true;}});document.addEventListener('drop',event=>{event.preventDefault();dragDepth=0;$('drop-overlay').hidden=true;if(!busy)loadFile(event.dataTransfer.files[0]);});document.addEventListener('paste',event=>{if(busy)return;const item=[...(event.clipboardData?.items||[])].find(item=>item.type.startsWith('image/'));if(item){event.preventDefault();loadFile(item.getAsFile());}});
window.addEventListener('pagehide',()=>{stopWorker();if(vectorURL)URL.revokeObjectURL(vectorURL);});updateLabels();sample();
